function validate([nums, k]) {
  const n = nums.length;
  if (n < 1 || n > 100000) return 'nums needs 1 to 100000 values.';
  const seen = new Array(n + 1).fill(false);
  for (const v of nums) {
    if (!Number.isInteger(v) || v < 1 || v > n) return 'Each value of nums is between 1 and nums.length.';
    if (seen[v]) return 'The values in nums must be distinct.';
    seen[v] = true;
  }
  if (!Number.isInteger(k) || k < 1 || k > n) return 'k is between 1 and nums.length.';
  return null;
}

