function countSubarrays(nums, k) {
  const pos = nums.indexOf(k);
  const seen = new Map([[0, 1]]);
  let prefix = 0;
  let result = 0;

  for (let i = 0; i < nums.length; i++) {
    if (nums[i] > k) {
      prefix++;
    } else if (nums[i] < k) {
      prefix--;
    }
    if (i < pos) {
      seen.set(prefix, (seen.get(prefix) ?? 0) + 1);
    } else {
      result += (seen.get(prefix) ?? 0) + (seen.get(prefix - 1) ?? 0);
    }
  }
  return result;
}

