function generate(rand, size) {
  const n = size === 'large' ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 9);
  const nums = Array.from({ length: n }, (_, i) => i + 1);
  const shape = rand();
  if (shape < 0.15) {
    // Keep it sorted.
  } else if (shape < 0.25) {
    nums.reverse();
  } else if (shape < 0.4) {
    // Alternate low and high values so balances stay near zero.
    const mixed = [];
    for (let low = 0, high = n - 1; low <= high; low++, high--) {
      mixed.push(nums[low]);
      if (low !== high) mixed.push(nums[high]);
    }
    nums.splice(0, n, ...mixed);
  } else {
    for (let i = n - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  }
  const k = rand() < 0.3 ? Math.ceil(n / 2) : 1 + Math.floor(rand() * n);
  return [nums, k];
}
